/** Resolve make input (code or label) to VEHICLE_MAKES entry. */
function resolveVehicleMake(make) {
  if (!make) return null;
  var v = String(make).trim();
  var upper = v.toUpperCase().replace(/[\s\-]+/g, "_");
  for (var i = 0; i < VEHICLE_MAKES.length; i++) {
    var m = VEHICLE_MAKES[i];
    if (!m) continue;
    if (m.code === v || m.code === upper) return m;
    if (m.label && m.label.toLowerCase() === v.toLowerCase()) return m;
  }
  return null;
}
/**
 * Models for a make. Accepts make CODE (HONDA) or label (Honda).
 * MODELS_BY_MAKE is keyed by manufacturer display name.
 */
function modelsForMake(make) {
  if (!make) return MODELS_BY_MAKE["Other"] || ["Other"];
  var direct = MODELS_BY_MAKE[make];
  if (direct) return direct;
  var entry = resolveVehicleMake(make);
  if (entry) {
    if (MODELS_BY_MAKE[entry.label]) return MODELS_BY_MAKE[entry.label];
    if (MODELS_BY_MAKE[entry.code]) return MODELS_BY_MAKE[entry.code];
  }
  var keys = Object.keys(MODELS_BY_MAKE);
  var lower = String(make).toLowerCase();
  for (var j = 0; j < keys.length; j++) {
    if (keys[j].toLowerCase() === lower) return MODELS_BY_MAKE[keys[j]];
  }
  return MODELS_BY_MAKE["Other"] || ["Other"];
}
function makeCodeFromInput(make) {
  var e = resolveVehicleMake(make);
  return e ? e.code : (make ? String(make).trim().toUpperCase().replace(/[\s\-]+/g, "_") : null);
}

/**
 * Infer likely body style codes from make + model text (heuristic; free text still allowed).
 * Returns ordered codes, most likely first.
 */
function inferBodyStyleCodes(make, model) {
  var text = [make, model].filter(Boolean).join(" ").toLowerCase();
  if (!text.trim()) return [];
  var scores = {};
  function bump(code, n) {
    scores[code] = (scores[code] || 0) + (n || 1);
  }
  if (/\b(pickup|pick-up|pick up|f-?150|f-?250|f-?350|f-?450|silverado|sierra|tundra|tacoma|ridgeline|ranger|colorado|canyon|titan|frontier|gladiator|maverick|ram 1500|ram 2500|ram 3500)\b/.test(text)) bump("PICKUP", 5);
  if (/\b(minivan|sienna|odyssey|pacifica|carnival|grand caravan|town & country|town and country|sedona|quest|routan)\b/.test(text)) bump("MINIVAN", 5);
  if (/\b(transit|promaster|sprinter|express|savana|e-?series|e350|e450|metris|nv200|nv cargo|city express)\b/.test(text) || /\bcargo van\b/.test(text)) bump("VAN", 5);
  if (/\b(suv|crossover|cuv|rav4|cr-?v|hr-?v|pilot|passport|highlander|4runner|4-runner|sequoia|land cruiser|explorer|expedition|escape|bronco|edge|tahoe|suburban|yukon|traverse|equinox|blazer|trailblazer|enclave|encore|acadia|terrain|grand cherokee|wrangler|compass|renegade|pathfinder|armada|murano|rogue|kicks|santa fe|tucson|palisade|telluride|sorento|sportage|outback|ascent|forester|crosstrek|cx-?5|cx-?50|cx-?9|cx-?90|mdx|rdx|gx|lx|rx|nx|ux|q3|q5|q7|q8|x1|x3|x5|x7|glc|gle|gls|discovery|range rover|defender|macan|cayenne|model y|model x|id\.?4|envision)\b/.test(text)) bump("SUV", 4);
  if (/\b(crossover)\b/.test(text)) bump("CUV", 3);
  if (/\b(coupe|coup[eé]|mustang|camaro|challenger|corvette|supra|celica|brz|gr86|fr-?s|mx-?5|miata|s2000|z4|gt-?r|370z|350z|911|boxster|viper)\b/.test(text)) bump("COUPE", 4);
  if (/\b(hatch|hatchback|golf|gti|fit|yaris|prius c|leaf|bolt|i3|veloster|soul)\b/.test(text)) bump("HATCHBACK", 4);
  if (/\b(wagon|estate|combi|avant|sportwagen|allroad|v60|v90|alltrack)\b/.test(text) && !/\bminivan\b/.test(text)) bump("WAGON", 4);
  if (/\b(sedan|camry|accord|corolla|civic|altima|sentra|maxima|malibu|impala|sonata|elantra|optima|k5|fusion|taurus|charger|300\b|model 3|model s|legacy)\b/.test(text)) bump("SEDAN", 3);
  if (/\b(motorcycle|sportbike|cruiser|harley|ducati|ninja|gsx-?r|cbr|motocross)\b/.test(text)) bump("MOTORCYCLE", 5);
  if (/\b(scooter|moped|vespa|pcx)\b/.test(text)) bump("SCOOTER", 5);
  if (/\b(atv|utv|side[ -]?by[ -]?side|rzr|can-?am)\b/.test(text)) bump("ATV", 5);
  if (/\b(trailer|fifth wheel)\b/.test(text)) bump("TRAILER", 5);
  if (/\b(semi|tractor|sleeper|freightliner|kenworth|peterbilt|mack|volvo truck|cascadia)\b/.test(text)) bump("TRACTOR", 4);
  if (/\b(box truck|dump truck|flatbed|commercial truck|f-?650|f-?750|super duty)\b/.test(text)) bump("TRUCK", 3);
  if (/\b(rv|motorhome|winnebago|airstream)\b/.test(text)) bump("RV", 5);
  if (/\b(boat|jet ski|pwc|watercraft)\b/.test(text)) bump("BOAT", 5);
  if (/\b(snowmobile|ski-?doo)\b/.test(text)) bump("SNOWMOBILE", 5);
  if (/\b(golf cart|lsv)\b/.test(text)) bump("GOLF", 5);
  if (/\b(bus|coach)\b/.test(text)) bump("BUS", 4);

  var makeOnly = String(make || "").toLowerCase();
  if (/harley|ducati|triumph|ktm|royal enfield|aprilia|husqvarna/.test(makeOnly)) bump("MOTORCYCLE", 3);
  if (/freightliner|kenworth|peterbilt|mack|volvo truck|western star/.test(makeOnly)) bump("TRACTOR", 2);
  if (/yamaha golf|ezgo|club car/.test(makeOnly)) bump("GOLF", 3);

  return Object.keys(scores).sort(function (a, b) {
    return scores[b] - scores[a];
  });
}

/** Primary suggested body style code (or null). */
function suggestBodyStyle(make, model) {
  var codes = inferBodyStyleCodes(make, model);
  return codes.length ? codes[0] : null;
}

/**
 * Body style options ordered for make/model: suggested first, then remaining catalog.
 * Full catalog always available (searchable select is not a straightjacket).
 */
function bodyStylesForMakeModel(make, model) {
  var all = Array.isArray(VEHICLE_BODY_STYLES) ? VEHICLE_BODY_STYLES.slice() : [];
  var preferred = inferBodyStyleCodes(make, model);
  if (!preferred.length) return all;
  var byCode = {};
  all.forEach(function (b) {
    if (b && b.code) byCode[b.code] = b;
  });
  var out = [];
  var seen = {};
  preferred.forEach(function (code) {
    if (byCode[code] && !seen[code]) {
      out.push(byCode[code]);
      seen[code] = true;
    }
  });
  all.forEach(function (b) {
    if (b && b.code && !seen[b.code]) {
      out.push(b);
      seen[b.code] = true;
    }
  });
  return out;
}
